import networkx as nx
import numpy as np

# Define the grid layout
grid = np.array([
    [0, 2, 4, 8, 10],
    [1, 'X', 7, 'X', 12],
    [3, 6, 'X', 18, 14],
    [5, 'X', 15, 'X', 17],
    [9, 11, 13, 16, 19]
])

# Define the action set
actions = ['up', 'down', 'left', 'right']

# Create a directed graph to represent state connectivity
G = nx.DiGraph()

# Add nodes for each state
for i in range(grid.shape[0]):
    for j in range(grid.shape[1]):
        if grid[i, j] != 'X':
            G.add_node((i, j), value=grid[i, j], distance_to_goal=np.inf)

# Connect adjacent states
for i in range(grid.shape[0]):
    for j in range(grid.shape[1]):
        if grid[i, j] != 'X':
            for action in actions:
                new_i, new_j = i, j
                if action == 'up' and i > 0:
                    new_i -= 1
                elif action == 'down' and i < grid.shape[0] - 1:
                    new_i += 1
                elif action == 'left' and j > 0:
                    new_j -= 1
                elif action == 'right' and j < grid.shape[1] - 1:
                    new_j += 1

                if (new_i, new_j) != ((i, j)) and G.has_node((new_i, new_j)):
                    G.add_edge((i, j), (new_i, new_j))

# Calculate the optimal actions for each state
for node in G.nodes():
    G.nodes[node]['distance_to_goal'] = np.inf
    queue = [(node, 0)]
    visited = set()

    while queue:
        state, distance = queue.pop(0)
        if distance >= G.nodes[state]['distance_to_goal']:
            continue

        for neighbor in G.neighbors(state):
            if neighbor not in visited:
                G.nodes[neighbor]['distance_to_goal'] = min(G.nodes[neighbor]['distance_to_goal'], distance + 1)
                queue.append((neighbor, distance + 1))
                visited.add(neighbor)

# Cluster states based on their connectivity and relation to the goal
clusters = {}

for node in G.nodes():
    cluster_id = None

    # Check for rotational symmetry
    for rot in range(4):
        new_node = (node[0] - rot, node[1])
        if new_node in clusters:
            cluster_id = clusters[new_node]
            break

    # If no rotation matches, check for reflectional symmetry
    if cluster_id is None:
        new_node = (node[0], -node[1])
        if new_node in clusters:
            cluster_id = clusters[new_node]

    # If still not matched, create a new cluster
    if cluster_id is None:
        cluster_id = len(clusters)
        clusters[node] = cluster_id

    # Add other nodes to the same cluster based on connectivity and distance to goal
    for neighbor in G.neighbors(node):
        if (G.nodes[neighbor]['distance_to_goal'] == 0 or 
            G.nodes[neighbor]['distance_to_goal'] == np.inf or 
            cluster_id != clusters[neighbor]):
            cluster_id = len(clusters)
            clusters[node] = cluster_id
            clusters[neighbor] = cluster_id

# Print the clustering result
print("Clusters:")
for node in G.nodes():
    print(f"{node}: {clusters[node]}")

# Print the rationale for state groupings
print("\nRationale:")
for node1, node2 in [(node1, node2) for node1 in clusters.keys() for node2 in clusters.keys() if clusters[node1] == clusters[node2]]:
    print(f"States {node1} and {node2} are clustered together because they have similar connectivity and distance to goal.")
